/** SkillScanResult is M77. */
export interface SkillScanResult {
  scan: SkillScan;
  failure?: Failure;
}

/** SkillScanWarning is a degraded scan step (unreadable dir, cache rebuilt). */
export interface SkillScanWarning {
  toolId?: string;
  text: string;
}

/** SkillSkip is one skill the import left alone. */
export interface SkillSkip {
  name: string;
  reason: string;
}

/** SkillStage is the M88/M89 answer: a staged download and its candidates. */
export interface SkillStage {
  stageId: string;
  /** github | zip */
  kind: string;
  origin?: SkillOrigin;
  label: string;
  candidates: SkillStageCandidate[];
  skipped?: SkillStageSkip[];
  expiresAt: string;
}

/** SkillStageCandidate is one skill found inside a staged download. */
export interface SkillStageCandidate {
  id: string;
  name: string;
  description: string;
  files: number;
  bytes: number;
  /** ok | exists | too-large | duplicate | invalid-name */
  state: string;
  existing?: string;
}

/** SkillStageProgressEvent is E13: download/unpack progress (≤ 1 frame / 200 ms). */
export interface SkillStageProgressEvent {
  requestId: string;
  /** resolving | downloading | unpacking | scanning */
  phase: string;
  received: number;
  total?: number;
}

/** SkillStageResult is M88/M89. */
export interface SkillStageResult {
  stage?: SkillStage;
  cancelled?: boolean;
  failure?: Failure;
}

/** SkillStageSkip is one entry the unpacker refused to create. */
export interface SkillStageSkip {
  path: string;
  /** symlink | special */
  reason: string;
}

/** SkillTarget is one registered custom tool or project (FR-SKM-CUSTOM/PROJ). */
export interface SkillTarget {
  /** t-<12 hex> */
  id: string;
  /** custom | project */
  kind: string;
  name: string;
  /** redacted for display; never the absolute path */
  path: string;
  /** project: project-relative install subdir */
  installDir?: string;
  /** registered dir still on disk */
  exists: boolean;
  /** quick count, SKILL.md content is not read */
  skillCount: number;
  /** project only */
  dirs?: SkillTargetDir[];
  createdAt: string;
}

/** SkillTargetDir is one conventional subdirectory of a project target. */
export interface SkillTargetDir {
  /** project-relative, slash-separated, e.g. ".claude/skills" */
  rel: string;
  /** false only for installDir before it is created */
  exists: boolean;
  /** immediate subdirectories holding a SKILL.md */
  skills: number;
}

/** SkillTargetsResult is M97. */
export interface SkillTargetsResult {
  items: SkillTarget[];
  failure?: Failure;
}

/**
 * SkillTool is one entry of the built-in tool registry plus its detection
 * result (FR-SKM-TOOL/DETECT; paths are already redacted for display).
 */
export interface SkillTool {
  /** stable id, e.g. "claude-code", "agents" */
  id: string;
  /** display name */
  name: string;
  /** brand svg key; "globe" for the shared dir, "" for a letter placeholder */
  iconKey: string;
  installDir?: string;
  scanDirs: string[];
  /** tools that read the shared ~/.agents/skills */
  readers?: string[];
  /** detected | leftover | missing */
  status: string;
  /** M6: builtin | custom | project */
  kind: string;
  /** M6: registered dir is gone (custom/project) */
  missing?: boolean;
  /** M6: project install subdir for the target grid */
  installRel?: string;
  /** false = official support not verified */
  official: boolean;
  /** MiniMax Code defaults to false */
  enabled: boolean;
}

/** SkillToolRef is one extra tool copy of the same skill (M82 extras). */
export interface SkillToolRef {
  toolId: string;
  path: string;
}

/** SkillToolScan groups tool skills by tool. */
export interface SkillToolScan {
  toolId: string;
  skills: ToolSkill[];
}

/** SkillUninstallPreview is M80's answer before removing anything. */
export interface SkillUninstallPreview {
  /** link | copy | independent */
  kind: string;
  target?: string;
  backupPath?: string;
  affectedTools?: string[];
}

/** SkillUninstallResult is M80. */
export interface SkillUninstallResult {
  preview: SkillUninstallPreview;
  failure?: Failure;
}

/** SkillUpdateCheckResult is M93. */
export interface SkillUpdateCheckResult {
  checkedAt: string;
  checking: boolean;
  groups: number;
  unchecked: number;
  rateLimitResetAt?: string;
}

/** SkillUpdateFile is one entry of the update diff. */
export interface SkillUpdateFile {
  path: string;
  /** added | modified | removed */
  change: string;
  bytes: number;
  binary?: boolean;
}

/** SkillUpdatePreviewResult is M94. */
export interface SkillUpdatePreviewResult {
  stageId?: string;
  from?: string;
  to?: string;
  files?: SkillUpdateFile[];
  plan?: MutationPlan;
  backupPath?: string;
  failure?: Failure;
}

/** SkillUpdateTarget is one skill M94 previews an update for. */
export interface SkillUpdateTarget {
  /** kb | tool */
  kind: string;
  skillPath?: string;
  toolId?: string;
  /** wire spec (§12.3) */
  path?: string;
}

/** SkillsChangedEvent is E12: background scan or skill operation finished. */
export interface SkillsChangedEvent {
  sequence: number;
}

/** StatusFrame is a turn-phase or retry hint (§6). */
export interface StatusFrame {
  state: string;
  phase?: string;
  model?: string;
  effort?: string;
  detail?: string;
}

/** StorageLocation is one row of M74's storage list. */
export interface StorageLocation {
  kind: string;
  label: string;
  display: string;
  copyable: boolean;
}

/** StreamFrame is the M39 channel union (§6); the frontend narrows on Kind. */
export interface StreamFrame {
  /** delta | thought | tool | permission | status | usage | turn-end | error */
  kind: string;
  seq: number;
  agent: string;
  sessionId: string;
  text?: string;
  toolCall?: ToolCallFrame;
  permission?: PermFrame;
  status?: StatusFrame;
  usage?: UsageFrame;
  stopReason?: string;
  message?: string;
  finish?: boolean;
}

/** TaskItem is one handoff task on the shared board. */
export interface TaskItem {
  id: string;
  owner: string;
  status: string;
  goal: string;
  inputs: string[];
  constraints: string[];
  outputs: string[];
  createdBy: string;
  createdAt: string;
  updatedAt: string;
}

/** ToolCallFrame is one tool call status line (§6). */
export interface ToolCallFrame {
  id: string;
  title: string;
  kind?: string;
  /** pending | in-progress | completed | failed */
  status: string;
  detail?: string;
}

/** ToolSkill is one skill found in a tool directory (FR-SKM-SCAN). */
export interface ToolSkill {
  name: string;
  description: string;
  path: string;
  toolId: string;
  /** linked | link-broken | copied | independent | builtin | external-link */
  origin: string;
  /** in-sync | vault-updated | tool-updated | both-updated | missing */
  sync?: string;
  /** redacted target of a link */
  target?: string;
  /** copied: the vault skill it came from */
  sourcePath?: string;
  builtin?: boolean;
  /** install | scan:<n> | builtin:<n> | project:<dir> (API §12.3, §14) */
  base?: string;
  /** path inside that root, slash-separated */
  rel?: string;
  /** M6: project rows, the tool the subdir belongs to */
  sourceToolId?: string;
  /** M6: project rows, project-relative subdir */
  subdir?: string;
  /** M5: GitHub origin and update state */
  remote?: SkillRemote;
}

/** TransactionSummary is one transaction row in the audit panel. */
export interface TransactionSummary {
  id: string;
  planId: string;
  createdAt: string;
  status: string;
  entryCount: number;
}

/** TreeResult is one directory level. */
export interface TreeResult {
  vaultId: string;
  path: string;
  entries: FileEntry[];
  skillCategoryCount?: number;
  failure?: Failure;
}

/** UnavailableVault is a registered vault that cannot be opened right now. */
export interface UnavailableVault {
  id: string;
  root: string;
  displayName: string;
  /** missing | no-permission */
  reason: string;
}

/** UnresolvedLinkItem is one broken wiki/internal link (API.md M28). */
export interface UnresolvedLinkItem {
  from: string;
  target: string;
  candidates: number;
}

/** UntitledItem is a document whose title fell back to its file name. */
export interface UntitledItem {
  path: string;
  fileName: string;
}

/**
 * Usage is one usage group (turn or cumulative). Fields follow the legacy
 * shared/usage.ts:22-50; unknown cost/ratio stay nil and render as an em dash.
 */
export interface Usage {
  totalTokens: number;
  promptTokens: number;
  completionTokens: number;
  reasoningTokens: number;
  cacheHitTokens: number;
  cacheMissTokens: number;
  estimated?: boolean;
  cacheHitRatio?: number;
  estimatedCost?: number;
  currency?: string;
  costComplete?: boolean;
  displayStatus?: string;
  usageSource?: string;
}

/** UsageFrame is the per-step usage receipt (§6). */
export interface UsageFrame {
  turn: Usage;
  cumulative: Usage;
}

/** Vault is one registered, usable knowledge base. */
export interface Vault {
  id: string;
  root: string;
  displayName: string;
  createdAt?: string;
  lastOpenedAt?: string;
}

/** VaultChangedEvent tells the page which directory levels need a refresh. */
export interface VaultChangedEvent {
  vaultId: string;
  directories: string[];
  sequence: number;
}

/**
 * VaultContext mirrors shared/context.ts:85-91: the label is the display name,
 * never an absolute path.
 */
export interface VaultContext {
  id: string;
  rootLabel: string;
  revision: number;
  indexRevision: number;
}

/** VaultListResult is returned by list/open/forget/retry. */
export interface VaultListResult {
  vaults: Vault[];
  activeVaultId?: string;
  unavailable: UnavailableVault[];
  failure?: Failure;
}

/** WindowStateEvent mirrors maximize/focus changes for the self-drawn chrome. */
export interface WindowStateEvent {
  maximized: boolean;
  focused: boolean;
}

/** WriteOutcome is the save outcome union (API.md M18). */
export interface WriteOutcome {
  /** written | conflict */
  status: string;
  revision?: number;
  hash?: string;
  size?: number;
  diskText?: string;
  diskRevision?: number;
  diskHash?: string;
  diskSize?: number;
  baseRevision?: number;
  failure?: Failure;
}

/** WritePreview is the approval card's write preview (API §6). */
export interface WritePreview {
  /** created | modified | summary */
  kind: string;
  lines?: DiffLine[];
  oldLineCount?: number;
  newLineCount?: number;
  oldBytes: number;
  newBytes: number;
  /** too-large | not-text | unchanged */
  reason?: string;
}

// ---- Services ----

/** VaultService binds vault registration and the wizard. */
export const VaultService = {
  /** Choose opens the directory picker and registers the chosen vault. */
  choose: bind<[], ChooseVaultResult>("VaultService.Choose", () => []),
  /** CreateVault finishes the wizard. */
  createVault: bind<[string, boolean], ChooseVaultResult>("VaultService.CreateVault", (token: string, confirmNonEmpty: boolean) => [token, confirmNonEmpty]),
  /** Forget removes a vault and its recent documents. */
  forget: bind<[string], VaultListResult>("VaultService.Forget", (vaultID: string) => [vaultID]),
  /**
   * ImportSkills copies the selected skills into skills/<category>/ (M15). The
   * token is not consumed: a name that already exists can be retried under
   * another category until the token expires.
   */
  importSkills: bind<[string, string, string, string[]], ImportSkillsResult>("VaultService.ImportSkills", (vaultID: string, token: string, category: string, names: string[]) => [vaultID, token, category, names]),
  /** List returns the registered vaults. */
  list: bind<[], VaultListResult>("VaultService.List", () => []),
  /** Open makes a registered vault active. */
  open: bind<[string], VaultListResult>("VaultService.Open", (vaultID: string) => [vaultID]),
  /**
   * PickFolder is the wizard's first step: it returns an opaque token instead of
   * the absolute path.
   */
  pickFolder: bind<[], PickFolderResult>("VaultService.PickFolder", () => []),
  /**
   * PickSkillSource is the skill wizard's first step (M14): pick a folder, list
   * the skills one level down and hand back an opaque token.
   */
  pickSkillSource: bind<[], PickSkillSourceResult>("VaultService.PickSkillSource", () => []),
  /** Retry re-checks an unavailable vault. */
  retry: bind<[string], VaultListResult>("VaultService.Retry", (vaultID: string) => [vaultID]),
} as const;

/** SettingsService binds the application settings. */
export const SettingsService = {
  /** AboutInfo returns the about page payload (M74). */
  aboutInfo: bind<[], AboutInfoResult>("SettingsService.AboutInfo", () => []),
  /**
   * AppConfigGet returns the vault-level settings the UI reads (M62): display
   * aliases, the parsed category table and the four agents.
   */
  appConfigGet: bind<[string], AppConfigResult>("SettingsService.AppConfigGet", (vaultID: string) => [vaultID]),
  /** AppConfigPatchAgent merges one agent's patch and writes agents.json (M63). */
  appConfigPatchAgent: bind<[string, string, AgentPatch], AppConfigResult>("SettingsService.AppConfigPatchAgent", (vaultID: string, agent: string, patch: AgentPatch) => [vaultID, agent, patch]),
  /**
   * AppConfigPatchAliases applies alias edits (M66). A nil or empty value deletes
   * the entry; the file keeps byte compatibility with the legacy writer.
   */
  appConfigPatchAliases: bind<[string, Record<string, string | null>], AppConfigResult>("SettingsService.AppConfigPatchAliases", (vaultID: string, patches: Record<string, string | null>) => [vaultID, patches]),
  /**
   * AppConfigResetSteering restores one agent's default steering (M64). The
   * response carries the defaults; nothing is written until the user saves.
   */
  appConfigResetSteering: bind<[string, string], AppConfigResult>("SettingsService.AppConfigResetSteering", (vaultID: string, agent: string) => [vaultID, agent]),
  /**
   * AppConfigSetCategories writes the category table (M65). Invalid rows are
   * dropped and rows equal to the defaults are not persisted, matching the
   * legacy writer (数据库设计 3.2, D-013).
   */
  appConfigSetCategories: bind<[string, CategoryConfig[]], AppConfigResult>("SettingsService.AppConfigSetCategories", (vaultID: string, categories: CategoryConfig[]) => [vaultID, categories]),
  /**
   * CopyStoragePath writes a real path to the system clipboard (M75). The
   * credential store has no path to copy.
   */
  copyStoragePath: bind<[string], CopyStoragePathResult>("SettingsService.CopyStoragePath", (kind: string) => [kind]),
  /**
   * FetchModels asks a provider for its model list (M70). A draft key wins over
   * the stored one, matching the legacy handler.
   */
  fetchModels: bind<[string, string, string, string], FetchModelsResult>("SettingsService.FetchModels", (kind: string, baseURL: string, apiKeyEnv: string, apiKey: string) => [kind, baseURL, apiKeyEnv, apiKey]),
  /** Get returns the current settings. */
  get: bind<[], SettingsResult>("SettingsService.Get", () => []),
  /** Patch applies a partial update and broadcasts the result. */
  patch: bind<[SettingsPatch], SettingsResult>("SettingsService.Patch", (patch: SettingsPatch) => [patch]),
  /**
   * Providers returns the vault's provider definitions plus whether each key is
   * configured (M67). The key value never leaves the secret store.
   */
  providers: bind<[string], ProvidersResult>("SettingsService.Providers", (vaultID: string) => [vaultID]),
  /**
   * SaveProviders normalizes and validates the whole list, then writes it
   * atomically (M68). One invalid entry fails the save; nothing is written.
   */
  saveProviders: bind<[string, ProviderDraft[]], ProvidersResult>("SettingsService.SaveProviders", (vaultID: string, drafts: ProviderDraft[]) => [vaultID, drafts]),
  /**
   * SetKey stores one API key (M69). Like the legacy handler it refreshes the
   * snapshot for the active vault; without an active vault it only reports the
   * one credential it touched.
   */
  setKey: bind<[string, string], ProvidersResult>("SettingsService.SetKey", (envName: string, value: string) => [envName, value]),
  /**
   * SkillCatalog returns the skills the settings page can assign (M71). It is
   * derived from the index; before the index is open the list is empty.
   */
  skillCatalog: bind<[string], SkillCatalogResult>("SettingsService.SkillCatalog", (vaultID: string) => [vaultID]),
} as const;

/** DocService binds tree and document operations. */
